// Package submissions persists contact-form submissions and tracks
// the email-delivery status of each one. It is backed by PostgreSQL, with
// queries generated by sqlc (see the db subpackage).
package submissions

import (
	"context"
	"errors"
	"fmt"
	"time"

	pgmig "github.com/infodancer/web/contact/migrations/postgres"
	"github.com/infodancer/web/contact/submissions/db"
	"github.com/jackc/pgx/v5"
	"github.com/jackc/pgx/v5/pgxpool"
	"github.com/jackc/pgx/v5/stdlib"
	"github.com/pressly/goose/v3"
)

// migrationsTableName is contact's dedicated goose version table, distinct from
// the host's default goose_db_version so migration histories never collide when
// components share a database.
const migrationsTableName = "contact_goose_db_version"

// Submission represents a single contact-form message.
type Submission struct {
	ID        int64
	Name      string
	Email     string
	Subject   string
	Message   string
	IP        string
	UserAgent string
	CreatedAt time.Time
}

// Status values stored in the email_status column.
const (
	StatusPending = "pending"
	StatusSent    = "sent"
	StatusFailed  = "failed"
)

// Store persists submissions over a PostgreSQL connection pool.
type Store struct {
	q    *db.Queries
	pool *pgxpool.Pool
}

// New creates a Store over an existing pool. The caller owns the pool (typically
// the host's shared pool) and should apply the schema first with Migrate.
func New(pool *pgxpool.Pool) *Store {
	return &Store{q: db.New(pool), pool: pool}
}

// Pool returns the underlying connection pool.
func (s *Store) Pool() *pgxpool.Pool { return s.pool }

// Migrate applies the embedded PostgreSQL migrations against pool. It is safe to
// call repeatedly; goose tracks applied versions in contact_goose_db_version.
func Migrate(ctx context.Context, pool *pgxpool.Pool) error {
	sqldb := stdlib.OpenDBFromPool(pool)
	defer func() { _ = sqldb.Close() }()

	prov, err := goose.NewProvider(goose.DialectPostgres, sqldb, pgmig.FS,
		goose.WithTableName(migrationsTableName),
		goose.WithLogger(goose.NopLogger()),
	)
	if err != nil {
		return fmt.Errorf("contact: migrate: %w", err)
	}
	if _, err := prov.Up(ctx); err != nil {
		return fmt.Errorf("contact: migrate: %w", err)
	}
	return nil
}

// Save inserts a new submission and populates ID and CreatedAt on success.
func (s *Store) Save(ctx context.Context, sub *Submission) error {
	row, err := s.q.InsertSubmission(ctx, db.InsertSubmissionParams{
		Name:      sub.Name,
		Email:     sub.Email,
		Subject:   sub.Subject,
		Message:   sub.Message,
		Ip:        sub.IP,
		UserAgent: sub.UserAgent,
	})
	if err != nil {
		return fmt.Errorf("insert: %w", err)
	}
	sub.ID = row.ID
	sub.CreatedAt = row.CreatedAt
	return nil
}

// MarkSent records a successful delivery.
func (s *Store) MarkSent(ctx context.Context, id int64) error {
	return s.q.MarkSent(ctx, id)
}

// MarkFailed records a failed delivery attempt with the error message.
func (s *Store) MarkFailed(ctx context.Context, id int64, errMsg string) error {
	return s.q.MarkFailed(ctx, db.MarkFailedParams{ID: id, LastError: errMsg})
}

// Pending returns up to limit submissions whose email_attempts is below
// maxAttempts and whose status is pending or failed. Used by retry workers
// (slated for v0.2 — exposed now so the worker can be wired in without an
// API change).
func (s *Store) Pending(ctx context.Context, maxAttempts, limit int) ([]Submission, error) {
	rows, err := s.q.PendingSubmissions(ctx, db.PendingSubmissionsParams{
		MaxAttempts: int32(maxAttempts),
		RowLimit:    int32(limit),
	})
	if err != nil {
		if errors.Is(err, pgx.ErrNoRows) {
			return nil, nil
		}
		return nil, fmt.Errorf("query pending: %w", err)
	}
	out := make([]Submission, 0, len(rows))
	for _, r := range rows {
		out = append(out, Submission{
			ID:        r.ID,
			Name:      r.Name,
			Email:     r.Email,
			Subject:   r.Subject,
			Message:   r.Message,
			IP:        r.Ip,
			UserAgent: r.UserAgent,
			CreatedAt: r.CreatedAt,
		})
	}
	return out, nil
}
